'use strict';
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>{if(['ArrowRight','ArrowUpRight','ExternalLink'].includes(name))return bespokeArrow();const el=lucide.createElement(lucide.icons[name]);el.setAttribute('aria-hidden','true');el.setAttribute('class','icon');el.setAttribute('stroke-width','1.7');return el.outerHTML;};
const bespokeArrow=()=>'<svg class="bespoke-arrow" viewBox="0 0 20 20" aria-hidden="true"><g transform="translate(10 10) rotate(-45) translate(-8.834 -7.226)"><path fill="currentColor" d="M10.14 0.4C10.16 0.38 10.57 0.28 11.05 0.17C11.54 0.06 11.94 -0.02 11.95 0C11.96 0.02 12.01 0.36 12.06 0.76C12.17 1.54 12.44 2.47 12.73 3.04C13.62 4.84 15.23 6.03 17.17 6.34L17.67 6.41L17.67 7.21L17.67 8L17.22 8.08C14.28 8.57 12.36 10.77 12 14.06C11.98 14.28 11.95 14.45 11.94 14.45C11.84 14.45 10.2 14.05 10.16 14.02C10.14 14 10.16 13.8 10.2 13.58C10.68 11.1 12.04 9.09 13.81 8.25L14.23 8.04L5.51 8.03L0 8.02L0 6.41L5.53 6.4L14.22 6.39L13.69 6.12C12.3 5.41 11.2 4.03 10.55 2.18C10.37 1.65 10.09 0.45 10.14 0.4Z"/></g></svg>';
const actionArrow=()=>`<span class="btn-arrow">${bespokeArrow()}</span>`;
const entryGroup={'/music':'music','/no-music':'no-music'}[location.pathname.replace(/\/+$/,'')]||null;const hashToken=new URLSearchParams(location.hash.slice(1)).get('p');const storedToken=()=>{try{return localStorage.getItem('ym_token');}catch{return null;}};const rememberToken=t=>{token=t;try{localStorage.setItem('ym_token',t);}catch{}};let token=hashToken||(entryGroup?storedToken():null);let skipNextIntro=false;
const stageNames={t0:'Baseline check-in',allocation:'Ready for assignment',session:'Session in progress',wait_t2:'Finished listening, ready for T2',t2:'Pre-procedure check-in',recovery:'Ready for evening follow-up',evening:'Evening follow-up',followup:'Ready for sleep follow-up',sleep:'Sleep follow-up',done:'Journey complete'};
const formNames={t0:'Baseline',t2:'Before procedure',evening:'Evening',sleep:'First-night sleep'};
let csrf='',all=[],audioFiles=[],currentId=null,patientState=null,forms={},answers={},questionIndex=0,patientIntro=true,saveChain=Promise.resolve(),poller=null,search='',groupFilter='',revision=0,dirty=false,missing={};
const date=s=>s?new Date(s.replace(' ','T')+'Z').toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const groupName=g=>({audio:'With YouMind audio',usual:'Usual care · no audio',unassigned:'Not assigned'}[g]||'Not assigned');
const brand=()=>'<a class="brand" href="./"><img src="assets/youmind-official.webp" alt="YouMind"><span>Digital assessment</span></a>';
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),4000);}
async function api(action,data,extra={}){const headers={...extra};if(token)headers['X-Participant']=token;const options={headers,cache:'no-store'};if(data!==undefined){options.method='POST';headers['X-CSRF-Token']=csrf;if(data instanceof FormData)options.body=data;else{headers['Content-Type']='application/json';options.body=JSON.stringify(data);}}const r=await fetch('api.php?action='+action,options);let result;try{result=await r.json();}catch{throw new Error('The server is unavailable. Please try again.');}if(!r.ok)throw new Error(result.error||'Request failed.');return result;}
function accessLinks(p){const rows=p.study_group==='audio'?[['With music','/music']]:p.study_group==='usual'?[['Without music','/no-music']]:[['With music','/music'],['Without music','/no-music']];return rows.map(([label,path])=>`<div class="access-link"><span>${label}</span><code>${esc(location.origin+path)}</code><button type="button" class="btn ghost" data-copy="${esc(location.origin+path)}">${icon('Copy')}Copy</button></div>`).join('')+(p.study_group==='unassigned'?'<p class="small muted">Either link works until the group is chosen.</p>':'');}
function renderWelcome(){document.body.className='patient-body';app.innerHTML=`<header class="patient-header"><div class="brand"><img src="assets/youmind-official.webp" alt="YouMind"></div></header><main class="patient-main is-active"><section class="patient-card"><div class="question-heading"><span class="journey-icon"><img src="assets/head-pulse.svg" alt=""></span><div><h2>Share how you feel</h2><p>A few short questions, about 2 minutes. Taking part is voluntary and your answers do not change your medical care.</p></div></div><p class="save-status" id="welcome-error" role="alert"></p><button class="btn full journey-cta" id="welcome-start"><span>Start</span><span class="cta-arrow">${icon('ArrowRight')}</span></button><div class="question-secondary"><button type="button" id="welcome-code">Already started? Enter your study code</button></div></section></main>`;document.querySelector('#welcome-code').onclick=renderEntry;document.querySelector('#welcome-start').onclick=async e=>{const btn=e.currentTarget,err=document.querySelector('#welcome-error');err.textContent='';btn.disabled=true;try{const r=await api('enroll',{entry:entryGroup});rememberToken(r.token);skipNextIntro=true;await loadPatient();}catch(x){err.textContent=x.message;btn.disabled=false;}};}
function renderEntry(){document.body.className='patient-body';app.innerHTML=`<header class="patient-header"><div class="brand"><img src="assets/youmind-official.webp" alt="YouMind"></div></header><main class="patient-main is-active"><section class="patient-card"><div class="question-heading"><span class="journey-icon"><img src="assets/head-pulse.svg" alt=""></span><div><h2>Enter your study code</h2><p>Your study representative gave you this code. It looks like YM-AB12CD.</p></div></div><form id="entry-form" novalidate><div class="answer-area"><label class="sr-only" for="entry-code">Study code</label><input id="entry-code" class="number-answer" type="text" autocapitalize="characters" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="YM-" maxlength="24" required></div><p class="save-status" id="entry-error" role="alert"></p><button class="btn full journey-cta"><span>Continue</span><span class="cta-arrow">${icon('ArrowRight')}</span></button></form></section></main>`;document.querySelector('#entry-code').focus();document.querySelector('#entry-form').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button'),err=document.querySelector('#entry-error');err.textContent='';btn.disabled=true;try{const r=await api('enter',{code:document.querySelector('#entry-code').value,entry:entryGroup});rememberToken(r.token);location.hash='#p='+r.token;}catch(x){err.textContent=x.message;btn.disabled=false;}};}
function header(){return `<header class="topbar">${brand()}<div class="top-actions">${staffRole==='admin'?`<button class="btn secondary header-audio" id="audio-settings" aria-label="Audio library">${icon('Headphones')}<span>Audio library</span></button>`:''}<div class="account"><button class="account-toggle" id="account-toggle" aria-label="Account menu" aria-expanded="false" aria-controls="account-menu">${icon('UserRound')}${icon('ChevronDown')}</button><div class="account-menu" id="account-menu" hidden><div class="account-label">${roleNames[staffRole]||'Study team'}</div>${staffRole==='admin'?`<button id="team-settings">${icon('Users')}Team</button><button id="allocation-settings">${icon('ListOrdered')}Allocation sequence</button>`:''}<button id="change-password">${icon('KeyRound')}Change password</button><button id="signout">${icon('LogOut')}Sign out</button></div></div></div></header>`;}
function bindHeader(){document.querySelector('#signout').onclick=async()=>{await api('logout',{});location.reload();};const audioBtn=document.querySelector('#audio-settings');if(audioBtn)audioBtn.onclick=audioModal;const toggle=document.querySelector('#account-toggle'),menu=document.querySelector('#account-menu');toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',!menu.hidden);};const allocBtn=document.querySelector('#allocation-settings');if(allocBtn)allocBtn.onclick=()=>{menu.hidden=true;allocationSetupModal();};const teamBtn=document.querySelector('#team-settings');if(teamBtn)teamBtn.onclick=()=>{menu.hidden=true;teamModal();};document.querySelector('#change-password').onclick=()=>{menu.hidden=true;passwordModal();};}
function passwordModal(){modal('Change password',`<form><div class="field"><label for="old-password">Current password</label><input id="old-password" name="old" type="password" autocomplete="current-password" required></div><div class="field"><label for="new-password">New password</label><input id="new-password" name="new" type="password" autocomplete="new-password" minlength="12" required><span class="small muted">At least 12 characters.</span></div><button class="btn full">Save password</button></form>`,(el,close)=>el.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('password',{old:f.old.value,new:f.new.value});close();toast('Password updated.');}catch(err){formError(f,err.message);b.disabled=false;}});}
function modal(title,body,onReady){const oldFocus=document.activeElement;const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" aria-label="Close">${icon('X')}</button></div><div class="modal-body">${body}</div></section>`;document.body.append(el);document.body.classList.add('modal-open');const close=()=>{el.remove();document.body.classList.remove('modal-open');oldFocus?.focus();};el.querySelector('.close').onclick=close;el.addEventListener('click',e=>{if(e.target===el)close();});el.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const focusables=[...el.querySelectorAll('button,input,select,textarea,a[href],summary')].filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===focusables[0]){e.preventDefault();focusables.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusables.at(-1)){e.preventDefault();focusables[0].focus();}}});onReady?.(el,close);[...el.querySelectorAll('input,select,button')].find(x=>!x.disabled&&x.getClientRects().length)?.focus();}
function formError(form,message){let el=form.querySelector('.error');if(!el){el=document.createElement('div');el.className='error';el.setAttribute('role','alert');form.prepend(el);}el.textContent=message;el.scrollIntoView({block:'nearest'});}
function login(){document.body.className=staffRole==='viewer'?'role-viewer':'';app.innerHTML=`<header class="topbar">${brand()}</header><main class="login-layout"><section class="login-story"><div class="study-icon">${icon('ClipboardList')}</div><div class="eyebrow">YouMind digital assessment</div><h1>Manage your study.<br>Support each participant.</h1><p>Create participant links, follow both study groups, and review saved responses in one place.</p><div class="intro-meta"><span>Mobile-first experience</span><span>Connected to MySQL</span></div></section><form class="card login-form" id="login-form"><div class="eyebrow">Research team</div><h2>Welcome to your workspace</h2><p>Sign in to manage the YouMind pilot.</p><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button class="btn full"><span>Sign in</span>${actionArrow()}</button><p class="login-foot">Participant? Open the personal link your study representative shared with you. No sign-in needed.</p></form></main>`;document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('login',{username:f.username.value,password:f.password.value});await dashboard();}catch(err){formError(f,err.message);}finally{b.disabled=false;}};}
function concern(p){return p.assessments.some(a=>Object.entries(a.answers).some(([k,v])=>['t2_unwanted_effects','evening_intervention_issues','sleep_audio_unwanted_effects'].includes(k)&&['Yes','Unsure'].includes(v)));}
function progress(p){const types=p.sleep_opt_in?['t0','t2','evening','sleep']:['t0','t2','evening'];const n=types.filter(t=>p.assessments.some(a=>a.type===t&&a.status==='completed')).length;return `<div class="mini-progress">${types.map(t=>`<i class="${p.assessments.some(a=>a.type===t&&a.status==='completed')?'done':''}"></i>`).join('')}</div><span class="small muted">${n} of ${types.length} check-ins</span>`;}
let staffRole='admin';const roleNames={admin:'Administrator',representative:'Representative',viewer:'Viewer'};
async function refreshData(){const r=await api('list');staffRole=r.role||'viewer';all=r.participants;audioFiles=r.audio;forms=r.forms;}
async function dashboard(){clearInterval(poller);await refreshData();currentId=null;renderDashboard();poller=setInterval(async()=>{if(document.querySelector('.modal-backdrop,.account-menu:not([hidden])'))return;try{await refreshData();if(currentId===null){renderStats();renderRows();const report=document.querySelector('#study-reports');if(report&&!report.contains(document.activeElement)){const panel=report.querySelector('.reports-panel'),wasOpen=panel?.open??true,active=report.querySelector('.report-tab[aria-selected="true"]')?.id;report.innerHTML=reportPanel();const next=report.querySelector('.reports-panel');if(next)next.open=wasOpen;setupReportTabs(report);if(active)report.querySelector('#'+active)?.click();}}}catch{}},10000);}
function renderDashboard(){document.body.className=staffRole==='viewer'?'role-viewer':'';app.innerHTML=header()+`<main class="workspace"><div class="heading-row"><div><h1>Study overview</h1></div><div class="button-row"><span id="bulk"></span><a class="btn secondary" href="api.php?action=export">${icon('Download')}Export CSV</a><button class="btn" id="add-participant">${icon('Plus')}Add participant</button></div></div><section class="stats" id="stats"></section><section class="table-card"><div class="toolbar"><h3>Participants <span class="muted" id="count"></span></h3><div class="filters"><input class="search" id="search" type="search" aria-label="Find participant" placeholder="Find a study ID or site…" value="${esc(search)}"><select id="group-filter" aria-label="Filter by group"><option value="">All groups</option><option value="audio">With music</option><option value="usual">Without music</option><option value="unassigned">Unassigned</option></select></div></div><div class="participant-row table-head"><span>Participant</span><span class="site-col">Study site</span><span>Group</span><span>Progress</span><span></span></div><div id="rows"></div></section><div id="study-reports">${reportPanel()}</div></main>`;bindHeader();renderStats();renderRows();document.querySelector('#add-participant').onclick=createModal;document.querySelector('#search').oninput=e=>{search=e.target.value;renderRows();};document.querySelector('#group-filter').value=groupFilter;document.querySelector('#group-filter').onchange=e=>{groupFilter=e.target.value;renderRows();};styleStudySelects(document.querySelector('.filters'));setupReportTabs(document.querySelector('#study-reports'));}
function renderStats(){document.querySelector('#stats').innerHTML=[['Participants',all.length],['With music',all.filter(p=>p.study_group==='audio').length],['Without music',all.filter(p=>p.study_group==='usual').length],['Completed check-ins',all.reduce((n,p)=>n+p.assessments.filter(a=>a.status==='completed').length,0)]].map(([label,n])=>`<article class="stat"><span>${label}</span><strong>${n.toString()}</strong></article>`).join('');}
function renderRows(){const filtered=all.filter(p=>(!groupFilter||p.study_group===groupFilter)&&`${p.code} ${p.site}`.toLowerCase().includes(search.toLowerCase()));document.querySelector('#count').textContent=`(${all.length})`;document.querySelector('#rows').innerHTML=filtered.length?filtered.map(p=>`<div class="participant-row" role="button" tabindex="0" data-id="${p.id}" aria-label="Open ${esc(p.code)}"><div><strong>${esc(p.code)}</strong><p>${esc(stageNames[p.stage])}${concern(p)?' · <span style="color:var(--attn)">Review concern</span>':''}</p></div><span class="site-col small muted">${esc(p.site)}</span><div><span class="pill ${p.study_group==='unassigned'?'amber':''}">${groupName(p.study_group)}</span></div><div class="row-progress">${progress(p)}${quickLabel(p)?`<button class="btn secondary row-open" data-open="${p.id}">${quickLabel(p)}</button>`:''}</div><span class="row-arrow">${icon('ChevronRight')}</span></div>`).join(''):`<div class="empty"><div class="study-icon">${icon('ClipboardList')}</div><h2>${all.length?'No matching participants':'Your study starts here'}</h2><p>${all.length?'Try another study ID or group.':'Add your first participant to create a personal link and begin the journey.'}</p>${!all.length?`<button class="btn secondary" id="empty-add"><span>Add first participant</span>${bespokeArrow()}</button>`:''}</div>`;document.querySelectorAll('[data-id]').forEach(el=>{el.onclick=()=>navigateParticipant(Number(el.dataset.id));el.onkeydown=e=>{if(e.target!==el)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=async e=>{e.stopPropagation();b.disabled=true;try{await api('advance',{id:Number(b.dataset.open)});await refreshData();renderRows();renderStats();updateBulk();}catch(err){toast(err.message);b.disabled=false;}});document.querySelector('#empty-add')?.addEventListener('click',createModal);updateBulk();}
function quickLabel(p){return {session:'Open T2',wait_t2:'Open T2',recovery:'Open evening',followup:'Open sleep'}[p.stage]||'';}
function updateBulk(){const slot=document.querySelector('#bulk');if(!slot)return;const kinds=[['recovery','evening','Open evening for all'],['followup','sleep','Open sleep for all']];slot.innerHTML=kinds.map(([stage,key,label])=>{const n=all.filter(p=>p.stage===stage).length;return n?`<button class="btn secondary" data-bulk="${stage}">${label} (${n})</button>`:'';}).join('');slot.querySelectorAll('[data-bulk]').forEach(btn=>btn.onclick=()=>{const stage=btn.dataset.bulk,[,key,label]=kinds.find(k=>k[0]===stage),waiting=all.filter(p=>p.stage===stage);modal(label+'?',`<p>This opens the ${key} questionnaire for ${waiting.length} waiting participant${waiting.length===1?'':'s'}.</p><button class="btn full" id="confirm-open-all">Open for all</button>`,(el,close)=>el.querySelector('#confirm-open-all').onclick=async e=>{e.target.disabled=true;let ok=0,fail=0;for(const p of waiting){try{await api('advance',{id:p.id});ok++;}catch{fail++;}}close();await refreshData();renderRows();renderStats();toast(fail?`Opened ${ok}, ${fail} not yet due.`:`Opened for ${ok}.`);});});}
function createModal(){modal('Add a participant',`<form id="create-form"><div class="field"><label for="site">Study site</label><input id="site" name="site" placeholder="e.g. ProActive Pain Center" maxlength="100" required></div><label class="check"><input name="consent" type="checkbox" required><span>Eligibility and consent confirmed</span></label><label class="check"><input name="sleep" type="checkbox"><span>Opted into next-morning sleep follow-up</span></label><button class="btn full" style="margin-top:22px"><span>Create participant</span>${actionArrow()}</button></form>`,(el,close)=>{el.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const r=await api('create',{site:f.site.value,consent:f.consent.checked,sleep:f.sleep.checked});close();await refreshData();await navigateParticipant(all.find(p=>p.code===r.code).id);}catch(err){formError(f,err.message);b.disabled=false;}};});}
function linkFor(p){return `${location.origin}${location.pathname}#p=${p.token}`;}
async function detail(id){clearInterval(poller);await refreshData();currentId=id;renderDetail();poller=setInterval(async()=>{if(document.querySelector('.modal-backdrop,.account-menu:not([hidden])'))return;try{const before=JSON.stringify(all.find(p=>p.id===id));await refreshData();if(currentId===id&&before!==JSON.stringify(all.find(p=>p.id===id))){const opened=[...document.querySelectorAll('.workspace details')].map(d=>d.open);const y=scrollY;renderDetail();document.querySelectorAll('.workspace details').forEach((d,i)=>d.open=!!opened[i]);window.scrollTo(0,y);}}catch{}},10000);}
function renderDetail(){const p=all.find(x=>x.id===currentId);if(!p)return;const url=linkFor(p);const activeForms=p.sleep_opt_in?['t0','t2','evening','sleep']:['t0','t2','evening'];app.innerHTML=header()+`<main class="workspace"><button class="btn ghost back" id="back">${icon('ArrowLeft')}All participants</button><div class="heading-row"><div><h1>${esc(p.code)}</h1><p>${esc(p.site)}</p></div><span class="pill ${p.study_group==='unassigned'?'amber':''}">${groupName(p.study_group)}</span></div><div class="detail-grid"><div class="stack"><section class="card"><div class="detail-card-head"><h2>The next step</h2><span class="pill">${esc(stageNames[p.stage])}</span></div>${nextAction(p)}<div class="button-row study-actions"><button class="btn secondary" id="study-record">${icon('ClipboardList')}Study record</button>${p.study_group!=='unassigned'?`<button class="btn secondary" id="change-group">${icon('ArrowLeftRight')}Change group</button>`:''}${['t0','session','wait_t2','t2','evening','sleep'].includes(p.stage)?`<button class="btn secondary" id="close-assessment" aria-label="Close interrupted assessment">${icon('CircleStop')}<span>Close assessment</span></button>`:''}</div></section>${listeningCard(p)}<section class="card"><h2>Assessment journey</h2>${activeForms.map((t,i)=>{const a=p.assessments.find(a=>a.type===t);return `<div class="timeline"><span class="step-dot ${a?.status==='completed'?'complete':''}">${a?.status==='completed'?'✓':i+1}</span><div><strong>${formNames[t]}</strong><p>${a?`${a.status[0].toUpperCase()+a.status.slice(1)} · Last saved ${date(a.saved_at)}`:'Not started'}</p></div></div>`;}).join('')}</section>${concern(p)?`<aside class="concern-notice">${icon('TriangleAlert')}<div><strong>Concern needs review</strong><p>Review the participant’s responses and follow the study safety process.</p><small>No clinical alert has been sent.</small></div></aside>`:''}${recordedResponses(p)}</div><aside class="stack"><section class="card access-card"><h2>Patient access</h2><div class="access-code">${esc(p.code)}</div><button class="btn secondary" id="copy-code">${icon('Copy')}Copy code</button><div class="access-links">${accessLinks(p)}</div><p class="small muted">The patient scans the QR code for their group, then types this code.</p><a class="access-preview" href="${esc(url)}" target="_blank" rel="noopener">Preview the patient screens</a></section><section class="card session-card"><details class="quiet-details"><summary>Session details</summary><div class="answer-row"><span>Started</span><strong>${date(p.session_started_at)}</strong></div><div class="answer-row"><span>Finished</span><strong>${date(p.session_ended_at)}</strong></div><div class="answer-row"><span>Recorded audio playback</span><strong>${Math.floor(p.listening_seconds/60)}m ${p.listening_seconds%60}s</strong></div><p class="small" style="margin-top:15px">${p.sleep_opt_in?'Optional sleep follow-up enabled.':'Optional sleep follow-up not selected.'}</p><button class="btn ghost" id="audit">Activity history</button></details></section></aside></div></main>`;bindHeader();document.querySelector('#back').onclick=returnToParticipants;document.querySelector('#study-record').onclick=()=>operationsModal(p);document.querySelector('#close-assessment')?.addEventListener('click',()=>closeAssessmentModal(p));document.querySelector('#change-group')?.addEventListener('click',()=>changeGroupModal(p));document.querySelector('#listen-notes')?.addEventListener('click',()=>operationsModal(p));document.querySelector('#copy-code').onclick=()=>copy(p.code);document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(b.dataset.copy));document.querySelector('#manual-group')?.addEventListener('click',()=>manualGroupModal(p));document.querySelector('#allocate')?.addEventListener('click',()=>allocateModal(p));document.querySelector('#advance')?.addEventListener('click',async e=>{e.target.disabled=true;try{await api('advance',{id:p.id});await refreshData();renderDetail();toast('The next questionnaire is now open.');}catch(err){toast(err.message);e.target.disabled=false;}});document.querySelector('#audit').onclick=async()=>{try{const rows=await api('audit&id='+p.id);modal('Activity history',rows.map(r=>`<div class="answer-row"><strong>${esc(r.action.replaceAll('_',' '))}</strong><span>${date(r.created_at)} · ${esc(r.actor)}</span></div>`).join(''));}catch(e){toast(e.message);}};}
function recordedResponses(p){return `<section class="card responses-card"><div class="detail-card-head"><h2>Recorded responses</h2><a class="btn secondary" href="api.php?action=export">${icon('Download')}<span>Export all</span></a></div><div class="response-groups">${p.assessments.length?p.assessments.map(a=>{const rows=Object.entries(a.answers).map(([k,v])=>responseRow(a,k,v,false)).join('')+Object.entries(a.missing||{}).filter(([,v])=>v!=='not_applicable').map(([k,v])=>responseRow(a,k,v,true)).join('');const status=a.status.charAt(0).toUpperCase()+a.status.slice(1);return `<details class="response-group" ${a.type===p.assessments.at(-1).type?'open':''}><summary><span class="response-form-name">${icon('ClipboardList')}${esc(formNames[a.type])}</span><span class="response-badges"><span class="response-status ${a.status==='completed'?'is-complete':''}">${esc(status)}</span>${a.status!=='completed'&&['t0','t2'].includes(a.type)&&a.core_completed?'<span class="response-status is-complete">Core complete</span>':''}</span><span class="response-chevron">${icon('ChevronDown')}</span></summary><div class="response-content">${responseSnapshot(a)}<details class="response-full quiet-details"><summary>Questions &amp; answers</summary><div class="response-meta"><span>Opened <time>${date(a.opened_at)}</time></span><span>Submitted <time>${date(a.submitted_at)}</time></span></div><dl class="response-list">${rows||'<div class="response-empty">No answers recorded.</div>'}</dl></details></div></details>`;}).join(''):`<div class="response-empty">${icon('ClipboardList')}<p>Responses appear here as the participant answers.</p></div>`}</div></section>`;}
function responseRow(a,key,value,isMissing){const q=forms[a.type]?.questions.find(q=>q.id===key);const display=Array.isArray(value)?value.map(v=>q?.labels?.[v]||v).join(', '):(q?.labels?.[value]||value);return `<div class="response-item ${!isMissing&&q?.type==='scale'?'is-score':''}"><dt>${esc(q?.title||(key==='sleep_total_duration_minutes'?'Total sleep (calculated)':key.replaceAll('_',' ')))}</dt><dd class="${isMissing?'is-missing':''}">${esc(display)}${!isMissing&&key==='sleep_total_duration_minutes'?' minutes':''}${!isMissing&&key==='sleep_total_hours'?' hours':''}${!isMissing&&key==='sleep_total_minutes'?' minutes':''}${!isMissing&&q?.type==='scale'?'<small>/ 10</small>':''}</dd></div>`;}
function nextAction(p){if(p.study_group==='unassigned'&&['t0','allocation'].includes(p.stage))return `<button class="btn" id="manual-group"><span>Choose group</span>${actionArrow()}</button>`;if(p.stage==='allocation')return `<p>Baseline is complete. Assign the participant using your approved allocation record.</p><button class="btn" id="allocate"><span>Assign study group</span>${actionArrow()}</button>`;if(p.stage==='recovery'||p.stage==='followup')return `<p>${p.stage==='recovery'?'When it is time for the evening follow-up, open the questionnaire below.':'When it is time for the next-morning follow-up, open the optional sleep questionnaire.'} The personal link stays the same.</p><button class="btn" id="advance"><span>Open ${p.stage==='recovery'?'evening':'sleep'} questionnaire</span>${actionArrow()}</button>`;if(p.stage==='session'||p.stage==='wait_t2')return `<p>${p.stage==='wait_t2'?'The participant has finished listening.':'The participant is in the listening or waiting period.'} When they are ready, open the before-procedure questionnaire.</p><button class="btn" id="advance"><span>Open before-procedure questionnaire</span>${actionArrow()}</button>`;if(p.stage==='done')return '<p>Assessments closed. Saved responses are below.</p>';return '<p>Awaiting the participant’s next step.</p>';}
function audioModal(){modal('Study recording',`${audioFiles[0]?`<div class="audio-library-row">${icon('Headphones')}<span><strong>${esc(recordingLabel(audioFiles[0]))}</strong>${audioFiles[0].description?`<br><small>${esc(audioFiles[0].description)}</small>`:''}</span></div><p class="small muted">This one recording is used for everyone in the With music group and for the optional sleep session. Uploading a new file replaces it.</p>`:'<p class="small muted">No recording uploaded yet.</p>'}<form><div class="field"><label for="audio-title">Title</label><input id="audio-title" name="title" required maxlength="120" placeholder="Pre-procedure session"></div><div class="field"><label for="audio-desc">Short description (optional)</label><input id="audio-desc" name="description" maxlength="300" placeholder="A calm listening session before your procedure."></div><div class="field"><label for="audio-file">Audio file</label><input id="audio-file" name="audio" type="file" accept=".mp3,.wav,.ogg,.m4a" required aria-describedby="audio-formats"><span class="upload-formats" id="audio-formats">MP3, WAV, OGG or M4A. Max 100 MB.</span></div><button class="btn full">${audioFiles[0]?'Replace recording':'Upload recording'}</button></form>`,(el,close)=>{el.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;b.textContent='Uploading…';try{await api('upload',new FormData(f));await refreshData();close();toast('Recording uploaded.');}catch(err){formError(f,err.message);b.disabled=false;b.textContent='Upload recording';}};});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Personal link copied.');}catch{modal('Copy personal link',`<div class="field"><textarea readonly>${esc(text)}</textarea></div>`,el=>el.querySelector('textarea').select());}}
/* Patient flow */
function stageIcon(){const t=patientState.stage;return t==='sleep'?'moon':t==='evening'?'hands-heart':'head-pulse';}
function journeyProgress(label,current,total){return `<div class="journey-progress"><div><span>${esc(label)}</span></div><div class="journey-track" role="progressbar" aria-label="Questionnaire progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${current}"><span style="width:${current/total*100}%"></span></div></div>`;}
const fmtTime=s=>{s=isFinite(s)?s:0;return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');};
function playerMarkup(a,src,id){const desc=a?.description||'';return `<div class="ym-player"><div class="ym-player-art"><img src="assets/head-pulse.svg" alt=""></div><div class="ym-player-body">${desc?`<p class="ym-player-desc">${esc(desc)}</p>`:''}<h2 class="ym-player-title">${esc(a?.title||'Listening session')}</h2><div class="ym-player-controls"><button type="button" class="ym-play" data-p="play" aria-label="Play"><svg class="ym-i-play" width="24" height="24" viewBox="0 0 24 24" fill="none"><path d="M8 6.5v11l10-5.5L8 6.5z" fill="currentColor"/></svg><svg class="ym-i-pause" width="24" height="24" viewBox="0 0 24 24" fill="none"><path d="M8 6h3v12H8V6zm5 0h3v12h-3V6z" fill="currentColor"/></svg></button><button type="button" class="ym-ctrl ym-vol" data-p="mute" aria-label="Mute"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 9v6h4l5 4V5L9 9H5z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path class="ym-wave" d="M16.5 9.5a3.5 3.5 0 010 5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path class="ym-wave" d="M19 7a6.5 6.5 0 010 10" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" opacity=".75"/><path class="ym-off" d="M18 8l4 8M22 8l-4 8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button></div><input type="range" class="ym-progress" min="0" max="1000" value="0" aria-label="Progress"><div class="ym-time"><span data-p="elapsed">00:00</span><span aria-hidden="true">|</span><span data-p="dur">--:--</span></div>${id?'<div class="ym-status" id="playback-status" role="status"></div>':''}</div><audio ${id?`id="${id}" `:''}preload="metadata" controlslist="nodownload" src="${src}"></audio></div>`;}
function bindPlayer(root){if(root.dataset.bound)return;root.dataset.bound='1';const a=root.querySelector('audio'),bar=root.querySelector('.ym-progress'),el=k=>root.querySelector('[data-p="'+k+'"]');const paint=()=>{const d=a.duration||0;bar.value=d?Math.round(a.currentTime/d*1000):0;bar.style.setProperty('--pct',bar.value/10+'%');el('elapsed').textContent=fmtTime(a.currentTime);el('dur').textContent=d?fmtTime(d):'--:--';};['timeupdate','loadedmetadata','durationchange','seeked'].forEach(ev=>a.addEventListener(ev,paint));a.addEventListener('play',()=>{el('play').classList.add('is-playing');el('play').setAttribute('aria-label','Pause');});['pause','ended'].forEach(ev=>a.addEventListener(ev,()=>{el('play').classList.remove('is-playing');el('play').setAttribute('aria-label','Play');}));el('play').onclick=()=>a.paused?a.play().catch(()=>{}):a.pause();el('mute').onclick=()=>{a.muted=!a.muted;el('mute').classList.toggle('is-muted',a.muted);};bar.oninput=()=>{if(a.duration)a.currentTime=bar.value/1000*a.duration;};if(root.closest('.sleep-access')){let acc=0,last=performance.now();const t=setInterval(()=>{if(!root.isConnected){clearInterval(t);a.pause();return;}const now=performance.now();if(!a.paused&&!a.ended)acc+=Math.min(2,(now-last)/1000);last=now;if(acc>=5){const n=Math.floor(acc);acc-=n;api('heartbeat',{seconds:Math.min(n,15),kind:'sleep'}).catch(()=>{});}},1000);}paint();}
function patientShell(content){document.body.className='patient-body';app.innerHTML=`<header class="patient-header"><div class="brand"><img src="assets/youmind-official.webp" alt="YouMind"></div></header><main class="patient-main ${patientIntro&&forms[patientState.stage]?'is-intro':'is-active'}">${patientState.is_test?`<div class="test-strip">Test participant</div>`:''}${content}${patientState.sleep_opt_in&&patientState.sleep_audio_id&&['recovery','followup'].includes(patientState.stage)?`<section class="sleep-access"><h3>Optional sleep audio</h3>${playerMarkup(patientState.audio,'api.php?action=audio&kind=sleep&token='+encodeURIComponent(token))}</section>`:''}</main>`;document.querySelectorAll('.ym-player').forEach(bindPlayer);app.querySelectorAll('button,a').forEach(control=>{[...control.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.includes('→')).forEach(node=>{node.textContent=node.textContent.replace(/\s*→/g,'');control.insertAdjacentHTML('beforeend',bespokeArrow());});});}
async function loadPatient(){clearInterval(poller);const r=await api('patient');patientState=r.participant;forms=r.forms;const saved=patientState.assessments.find(a=>a.type===patientState.stage);answers=saved?.answers||{};missing=saved?.missing||{};revision=saved?.revision||0;patientIntro=skipNextIntro?false:(!saved||!Object.keys(answers).length);skipNextIntro=false;questionIndex=Math.max(0,visibleQuestions().findIndex(q=>answers[q.id]===undefined&&!missing[q.id]));renderPatient();}
function visibleQuestions(){const out=[],clean={};for(const q of forms[patientState?.stage]?.questions||[]){if(q.when){const value=clean[q.when.field];if(!q.when.values.some(v=>Array.isArray(value)?value.includes(v):v===value))continue;}if(q.id!=='sleep_total_minutes')out.push(q);if(answers[q.id]!==undefined)clean[q.id]=answers[q.id];}return out;}
function renderPatient(){clearInterval(poller);const stage=patientState.stage;if(forms[stage]){if(patientIntro)renderIntro();else renderQuestion();return;}if(stage==='session'){renderSession();return;}const complete=stage==='done';const messages={allocation:['Your check-in is saved.','Please wait for your study representative.'],wait_t2:['Thank you.','Your study representative will let you know when it is time for the next step.'],recovery:['Thank you for checking in.','Follow your clinical team’s instructions. We’ll let you know when your evening check-in is ready. Keep your study code to sign back in.'],followup:['Thank you for sharing your day.','Tomorrow morning, scan the same QR code and enter your study code for your sleep check-in.'],done:['Thank you. You’re all done.','Your responses are saved. You can close this page.']};const [title,body]=messages[stage]||messages.done;patientShell(`<section class="patient-card waiting"><div class="success-icon">${icon('Check')}</div><h1>${title}</h1><p>${body}</p><p class="small">Your code: <strong>${esc(patientState.code)}</strong>. Show it to your study representative if asked.</p>${complete&&patientState.is_test?'<button class="btn secondary full" id="restart-test">Restart test walkthrough</button>':''}<details class="quiet-details"><summary>Assessment status</summary><div class="stage-list">${patientState.assessments.map(a=>`<div><span>${a.status==='completed'?'✓':'○'}</span><b>${formNames[a.type]}</b><span>${a.status==='completed'?'Saved':a.status}</span></div>`).join('')}</div>${entryGroup?'<button type="button" class="btn ghost" id="start-over">Not you? Start over on this phone</button>':''}</details></section>`);document.querySelector('#start-over')?.addEventListener('click',()=>{try{localStorage.removeItem('ym_token');}catch{}location.href=location.pathname;});document.querySelector('#restart-test')?.addEventListener('click',()=>modal('Restart this test?',`<p>This will archive the current test responses and start a new walkthrough.</p><button class="btn full" id="confirm-restart">Restart test</button>`,(el,close)=>el.querySelector('#confirm-restart').onclick=async()=>{try{await api('restart_test',{});close();dirty=false;await loadPatient();}catch(e){toast(e.message);}}));if(!complete)poller=setInterval(async()=>{try{const r=await api('patient');if(r.participant.stage!==stage)await loadPatient();}catch{}},5000);}
function renderIntro(){const f=forms[patientState.stage];const total=visibleQuestions().length;const titles={t0:['Before your','procedure.'],t2:['Your next','check-in.'],evening:['After your','procedure.'],sleep:['Your first-night','sleep check-in.']};const [top,accent]=titles[patientState.stage];const intro={t0:'Please answer the following questions based on how you feel right now.',t2:'Please answer based on how you feel right now, rather than how you felt earlier.',evening:'Please answer based on what you remember from today.',sleep:'Please answer based on last night. If you are unsure of an exact number, your best estimate is sufficient.'};patientShell(`<div class="journey-split"><section class="journey-copy"><h1>${top}<em>${accent}</em></h1><p>${intro[patientState.stage]}</p></section><section class="patient-card intro-card">${journeyProgress(f.label,0,total)}<div class="question-heading"><span class="journey-icon"><img src="assets/${stageIcon()}.svg" alt=""></span><div><h2>${formNames[patientState.stage]} assessment</h2></div></div>${patientState.stage==='evening'?'<p class="essential-note">This questionnaire is for research purposes and is not monitored as an emergency medical service. For urgent medical concerns, follow your clinic’s discharge instructions or seek appropriate urgent medical care.</p>':''}<button class="btn full journey-cta" id="begin"><span>Begin assessment</span><span class="cta-arrow">${icon('ArrowUpRight')}</span></button></section></div>`);document.querySelector('#begin').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{await saveNow(false);patientIntro=false;renderQuestion();document.querySelector('#question-title').focus({preventScroll:true});}catch(err){toast(err.message);button.disabled=false;}};}
function saveStatus(message,failed=false){const el=document.querySelector('#save-status');if(el){el.textContent=message;el.classList.toggle('failed',failed);}}
function cleanAnswers(){const result={};for(const q of visibleQuestions())if(answers[q.id]!==undefined)result[q.id]=answers[q.id];if(patientState.stage==='sleep'&&answers.sleep_total_minutes!==undefined)result.sleep_total_minutes=answers.sleep_total_minutes;return result;}
function queueSave(){dirty=true;saveStatus('Saving…');const payload={type:patientState.stage,answers:cleanAnswers(),missing:{...missing}};saveChain=saveChain.catch(()=>{}).then(()=>api('save',{...payload,revision})).then(r=>{revision=r.revision;if(JSON.stringify(payload.answers)===JSON.stringify(cleanAnswers())&&JSON.stringify(payload.missing)===JSON.stringify(missing)){dirty=false;saveStatus('Saved');}}).catch(err=>{saveStatus('Not saved yet. Check your connection and try again.',true);throw err;});saveChain.catch(()=>{});}
async function saveNow(submit,decline=false){for(const id of ['answer','sleep-hours','sleep-minutes'])clearTimeout(document.getElementById(id)?.saveTimer);await saveChain.catch(()=>{});saveStatus('Saving…');try{const r=await api('save',{type:patientState.stage,answers:cleanAnswers(),missing:{...missing},submit,decline,revision});revision=r.revision;dirty=false;saveStatus('Saved');return r;}catch(e){saveStatus('Not saved yet. Please try again.',true);throw e;}}
function renderQuestion(){const qs=visibleQuestions();questionIndex=Math.min(questionIndex,qs.length-1);const q=qs[questionIndex],v=answers[q.id];const f=forms[patientState.stage];let controls='';if(q.type==='scale')controls=`<div class="scale" role="group" aria-label="Select a number from 0 to 10">${Array.from({length:11},(_,i)=>`<button type="button" data-value="${i}" aria-pressed="${v===i}" class="${v===i?'selected':''}">${i}</button>`).join('')}</div><div class="anchors"><span>0 = ${esc(q.low)}</span><span>10 = ${esc(q.high)}</span></div>`;else if(q.type==='choice'||q.type==='multi')controls=`<div class="options">${q.options.map(o=>`<button type="button" data-value="${esc(o)}" aria-pressed="${Array.isArray(v)?v.includes(o):v===o}" class="option ${(Array.isArray(v)?v.includes(o):v===o)?'selected':''}">${esc(q.labels?.[o]||o)}</button>`).join('')}</div>`;else if(q.id==='sleep_total_hours')controls=`<div class="duration-fields"><label>Hours:<input class="number-answer" id="sleep-hours" type="number" min="0" max="24" step="1" inputmode="numeric" value="${esc(answers.sleep_total_hours??'')}"></label><label>Minutes:<input class="number-answer" id="sleep-minutes" type="number" min="0" max="59" step="1" inputmode="numeric" value="${esc(answers.sleep_total_minutes??'')}"></label></div>`;else if(q.type==='number')controls=`<label class="small muted" for="answer">${q.id.includes('minutes')?'Minutes':'Number'}</label><input class="number-answer" id="answer" type="number" min="0" max="${q.max}" step="1" inputmode="numeric" value="${esc(v??'')}">`;else controls=`<label class="small muted" for="answer">Please avoid names or other identifying details.</label><textarea class="text-answer" id="answer" maxlength="2000" placeholder="Your response…">${esc(v??'')}</textarea>`;
patientShell(`<section class="patient-card question-card">${journeyProgress(f.label,questionIndex+1,qs.length)}<div class="question-heading"><span class="journey-icon"><img src="assets/${stageIcon()}.svg" alt=""></span><div><div class="question-caption">${q.type==='multi'?'Select all that apply:':q.type==='scale'?'Select one number from 0 to 10.':q.type==='choice'?'Select one:':''}</div><h2 id="question-title" tabindex="-1">${esc(q.title)}</h2></div></div>${q.hint?`<p class="question-hint">${esc(q.hint)}</p>`:''}<div class="answer-area">${controls}</div><div id="save-status" class="save-status" role="status">${v!==undefined?'Saved':missing[q.id]?'Previously marked as '+esc(missing[q.id]):''}</div><div class="question-nav"><button class="btn ghost" id="previous">${icon('ArrowLeft')}Back</button><button class="btn journey-cta" id="next"><span>${questionIndex===qs.length-1?'Submit':'Continue'}</span><span class="cta-arrow">${icon('ArrowUpRight')}</span></button></div><div class="question-secondary"><button id="skip-question">Skip this question</button><button id="finish-later">Finish later</button></div></section><div class="end-note"><button class="btn ghost" id="decline">Decline this check-in</button><div></div></div>`);
document.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{delete missing[q.id];const value=q.type==='scale'?Number(b.dataset.value):b.dataset.value;if(q.type==='multi'){const arr=answers[q.id]||[];answers[q.id]=arr.includes(value)?arr.filter(x=>x!==value):[...arr,value];}else answers[q.id]=value;document.querySelectorAll('[data-value]').forEach(x=>{const val=q.type==='scale'?Number(x.dataset.value):x.dataset.value;const sel=Array.isArray(answers[q.id])?answers[q.id].includes(val):answers[q.id]===val;x.classList.toggle('selected',sel);x.setAttribute('aria-pressed',sel);});queueSave();});
document.querySelector('#answer')?.addEventListener('input',e=>{dirty=true;delete missing[q.id];answers[q.id]=q.type==='number'?(e.target.value===''?undefined:Number(e.target.value)):e.target.value;saveStatus('Not saved yet');clearTimeout(e.target.saveTimer);e.target.saveTimer=setTimeout(queueSave,500);});
document.querySelector('#next').onclick=async e=>{const value=answers[q.id];if(!missing[q.id]&&(value===undefined||value===''||(Array.isArray(value)&&!value.length))){toast('Please choose a response to continue.');return;}if(q.id==='sleep_total_hours'&&!missing[q.id]&&answers.sleep_total_minutes===undefined){toast('Enter both hours and minutes, or skip this question.');return;}const b=e.currentTarget;document.querySelectorAll('.patient-card button,.patient-card input,.patient-card textarea').forEach(el=>el.disabled=true);try{const isLast=questionIndex===visibleQuestions().length-1;await saveNow(isLast);if(isLast){await loadPatient();}else{questionIndex++;renderQuestion();document.querySelector('#question-title').focus();}}catch(err){toast(err.message);document.querySelectorAll('.patient-card button,.patient-card input,.patient-card textarea').forEach(el=>el.disabled=false);}};
for(const [id,key] of [['sleep-hours','sleep_total_hours'],['sleep-minutes','sleep_total_minutes']])document.getElementById(id)?.addEventListener('input',e=>{dirty=true;delete missing.sleep_total_hours;delete missing.sleep_total_minutes;answers[key]=e.target.value===''?undefined:Number(e.target.value);saveStatus('Not saved yet');clearTimeout(e.target.saveTimer);e.target.saveTimer=setTimeout(queueSave,500);});
document.querySelector('#skip-question').onclick=async e=>{delete answers[q.id];missing[q.id]='skipped';if(q.id==='sleep_total_hours'){delete answers.sleep_total_minutes;missing.sleep_total_minutes='skipped';}dirty=true;e.currentTarget.disabled=true;try{const last=questionIndex===visibleQuestions().length-1;await saveNow(last);if(last)await loadPatient();else{questionIndex++;renderQuestion();}}catch(err){toast(err.message);e.currentTarget.disabled=false;}};
document.querySelector('#previous').onclick=async()=>{try{await saveNow(false);if(questionIndex>0){questionIndex--;renderQuestion();}else{patientIntro=true;renderIntro();}}catch(e){toast(e.message);}};
document.querySelector('#finish-later').onclick=async()=>{try{await saveNow(false);modal('Your progress is saved','<p>You can close this page and return using the same personal link. Your saved answers will be waiting for you.</p>');}catch(e){toast(e.message);}};
document.querySelector('#decline').onclick=()=>modal('Decline this check-in?',`<p>Your existing responses will be kept, and this check-in will be marked as declined. Participation is voluntary.</p><button class="btn full" id="confirm-decline">Confirm decline</button>`,(el,close)=>el.querySelector('#confirm-decline').onclick=async e=>{e.target.disabled=true;try{await saveNow(false,true);close();await loadPatient();}catch(err){toast(err.message);e.target.disabled=false;}});
}
function renderSession(){const audio=patientState.study_group==='audio';patientShell(`<section class="patient-card ${audio?'':'waiting'}">${audio?'':`<div class="study-icon">${icon('Clock')}</div>`}<h1>${audio?'Your listening session':'Before your procedure'}</h1>${audio?'':'<p>Continue your usual pre-procedure waiting experience. Your study representative will let you know when to complete the next check-in.</p>'}${audio?playerMarkup(patientState.audio,'api.php?action=audio&token='+encodeURIComponent(token),'audio'):''}${audio?`<button class="btn full" id="session-end">I’m finished listening ${icon('ArrowRight')}</button>`:''}</section>`);
const player=document.querySelector('#audio');let seconds=0,last=performance.now();const watcher=setInterval(()=>api('patient').then(r=>{if(r.participant.stage!=='session'){clearInterval(watcher);loadPatient();}}).catch(()=>{}),5000);if(player){player.onerror=()=>document.querySelector('#playback-status').textContent='Audio could not load. Let your study representative know.';player.onplay=()=>{last=performance.now();api('heartbeat',{seconds:0}).catch(()=>{});};poller=setInterval(()=>{const now=performance.now();if(!player.paused&&!player.ended)seconds+=Math.min(2,(now-last)/1000);last=now;if(seconds>=5){const n=Math.floor(seconds);seconds-=n;api('heartbeat',{seconds:Math.min(n,15)}).catch(()=>{document.querySelector('#playback-status').textContent='Playback recording interrupted. Check your connection.';});}},1000);}
const endBtn=document.querySelector('#session-end');if(endBtn)endBtn.onclick=async e=>{e.target.disabled=true;player?.pause();try{if(player&&seconds>=1)await api('heartbeat',{seconds:Math.floor(seconds)});await api('session_end',{reason:audio?(player.ended?'Audio completed':'Participant continued / session stopped'):'Usual-care waiting interval finished'});await loadPatient();}catch(err){toast(err.message);e.target.disabled=false;}};
}
window.addEventListener('beforeunload',e=>{if(token&&dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>location.reload());
window.addEventListener('offline',()=>toast('Connection lost. Keep this page open; saving will resume when you retry.'));
(async()=>{try{const session=await api('session');csrf=session.csrf;if(token){try{await loadPatient();}catch(e){if(entryGroup&&!hashToken){try{localStorage.removeItem('ym_token');}catch{}token=null;renderWelcome();}else throw e;}}else if(entryGroup)renderWelcome();else if(session.staff)await dashboard();else login();}catch(e){app.innerHTML=`<main class="patient-main"><section class="card"><h2>We couldn’t open this page.</h2><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Try again</button></section></main>`;}})();

function responseSnapshot(a){
 const scores=(forms[a.type]?.questions||[]).filter(q=>q.type==='scale'&&a.missing?.[q.id]!=='not_applicable'&&(!q.when||q.when.values.some(v=>Array.isArray(a.answers[q.when.field])?a.answers[q.when.field].includes(v):a.answers[q.when.field]===v)));
 const labels={anxiety:'Anxiety',relaxation:'Relaxation',sleep_quality:'Sleep quality',sleep_audio_helpfulness:'Audio helpfulness'};
 const tiles=scores.map(q=>{const value=a.answers[q.id],has=Number.isFinite(value),label=labels[q.id]||labels[q.id.replace(/^(t0|t2)_/,'')]||q.title;return `<div class="snapshot-score"><div class="snapshot-label">${esc(label)}</div>${has?`<strong>${value}<small> / 10</small></strong><div class="snapshot-meter" aria-hidden="true">${Array.from({length:10},(_,i)=>`<i class="${i<value?'filled':''}"></i>`).join('')}</div><div class="snapshot-endpoints"><span>${esc(q.low)}</span><span>${esc(q.high)}</span></div>`:`<span class="snapshot-unanswered">${esc(a.missing?.[q.id]==='skipped'?'Skipped':'Not answered')}</span>`}</div>`;}).join('');
 let sleep='';if(a.type==='sleep'){
 const v=a.answers,has=k=>Object.hasOwn(v,k),duration=has('sleep_total_hours')&&has('sleep_total_minutes')?`${v.sleep_total_hours}h ${v.sleep_total_minutes}m`:has('sleep_total_hours')?`${v.sleep_total_hours}h (minutes not recorded)`:'Not answered';
 sleep=`<div class="sleep-snapshot">${[['Moon','Total sleep',duration],['Clock','Times awake',has('sleep_awakenings')?v.sleep_awakenings:'Not answered'],['Headphones','Listened to audio',has('sleep_audio_used')?v.sleep_audio_used:'Not answered']].filter(([ic])=>ic!=='Headphones'||a.missing?.sleep_audio_used!=='not_applicable').map(([ic,label,value])=>`<div>${icon(ic)}<span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div>`;
 }
 return `${sleep}${tiles?`<div class="snapshot-scores">${tiles}</div>`:!sleep?'<p class="snapshot-prompt">Open questions &amp; answers to review this check-in.</p>':''}`;
}

let navigationBusy=false, dashboardPosition=0, dashboardParticipant=null;
async function navigateParticipant(id){
 if(navigationBusy)return;
 dashboardPosition=scrollY;dashboardParticipant=id;
 await navigateWorkspace(()=>detail(id),0,'#back');
}
async function returnToParticipants(){await navigateWorkspace(dashboard,dashboardPosition,`[data-id="${dashboardParticipant}"]`);}
async function navigateWorkspace(action,y,focusSelector){
 if(navigationBusy)return;navigationBusy=true;app.setAttribute('aria-busy','true');
 try{await action();window.scrollTo({top:y,behavior:'instant'});const view=document.querySelector('.workspace');
 if(view&&!matchMedia('(prefers-reduced-motion: reduce)').matches)view.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:200,easing:'ease-out'});
 document.querySelector(focusSelector)?.focus({preventScroll:true});
 }catch(error){toast(error.message);}finally{navigationBusy=false;app.removeAttribute('aria-busy');}
}
document.addEventListener('click',event=>{if(!event.target.closest('.account')){const menu=document.querySelector('#account-menu');if(menu)menu.hidden=true;document.querySelector('#account-toggle')?.setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=document.querySelector('#account-menu');if(menu&&!menu.hidden){menu.hidden=true;document.querySelector('#account-toggle')?.setAttribute('aria-expanded','false');document.querySelector('#account-toggle')?.focus();}}});
